from retry import backoff_delay


def test_upper_bound_is_the_cap():
    delay = backoff_delay(attempt=2, base=1, max_delay=100, rand=lambda: 1.0)
    assert delay == 4  # min(100, 1 * 2**2) * 1.0


def test_lower_bound_is_zero():
    delay = backoff_delay(attempt=5, base=1, max_delay=100, rand=lambda: 0.0)
    assert delay == 0


def test_delay_never_exceeds_max_delay_for_large_attempts():
    delay = backoff_delay(attempt=50, base=1, max_delay=10, rand=lambda: 1.0)
    assert delay == 10


def test_default_rand_stays_in_bounds():
    for attempt in range(10):
        delay = backoff_delay(attempt=attempt, base=1, max_delay=20)
        assert 0 <= delay <= 20

